const input=document.querySelector('#design-address-search'),list=document.querySelector('#design-address-list'),count=document.querySelector('#design-address-count');
try{const response=await fetch('design-studies.json');if(!response.ok)throw Error('Catalog unavailable');const catalog=await response.json();const entries=catalog.studies.flatMap(study=>study.details.map(detail=>({...detail,slug:study.slug,url:study.url})));function render(){const q=input.value.toLowerCase(),items=entries.filter(e=>(e.slug+' '+e.id+' '+e.title+' '+e.design).toLowerCase().includes(q));count.textContent=items.length+' of '+entries.length+' labeled details across three complete sites';list.replaceChildren();for(const entry of items){const row=document.createElement('article');row.className='design-address-row';const eyebrow=document.createElement('span');eyebrow.textContent=entry.slug+' / '+(entry.section?'SECTION':'DETAIL');const title=document.createElement('h3');title.textContent=entry.title;const id=document.createElement('code');id.textContent='#'+entry.id;const description=document.createElement('p');description.textContent=entry.design;const link=document.createElement('a');link.href=entry.url+'#'+entry.id;link.textContent='Open this detail ↗';row.append(eyebrow,title,id,description,link);list.append(row)}}input.addEventListener('input',render);render()}catch{count.textContent='The address book could not load. Each study still has its own section map.'}
